/**
 * Skinned PBR Lit vertex shader.
 * Extends the lit shader with GPU-based skeletal animation support.
 * Supports up to 4 bone influences per vertex and 64 bones per skeleton.
 * Compiled with and without USE_INSTANCING (see chunks.ts); the instanced
 * variant reads each instance's bone palette from a float texture.
 */
export declare const skinnedVertexShader = "\nprecision highp float;\n\n// Vertex attributes\nattribute vec3 a_position;     // Vertex position\nattribute vec3 a_normal;       // Vertex normal\nattribute vec2 a_uv;           // Texture coordinates\nattribute vec4 a_tangent;      // Tangent for normal mapping (xyz = tangent, w = handedness)\n\n\nuniform mat4 u_worldMatrix;\n\n#ifdef USE_INSTANCING\nattribute vec4 a_instanceMatrix0;\nattribute vec4 a_instanceMatrix1;\nattribute vec4 a_instanceMatrix2;\nattribute vec4 a_instanceMatrix3;\nattribute vec4 a_instanceColor;\nattribute vec4 a_instanceEmissive;\nattribute vec4 a_instanceMaterial;\n#endif\n\nmat4 getWorldMatrix() {\n#ifdef USE_INSTANCING\n\treturn mat4(a_instanceMatrix0, a_instanceMatrix1, a_instanceMatrix2, a_instanceMatrix3);\n#else\n\treturn u_worldMatrix;\n#endif\n}\n\n// Inverse-transpose of the upper 3x3 (up to a positive scale factor, which\n// the callers remove by normalising). Built from the cofactor matrix so it\n// stays correct for non-uniform scale without needing inverse() (GLSL ES 3).\nmat3 getNormalMatrix(mat4 m) {\n\tvec3 c0 = m[0].xyz;\n\tvec3 c1 = m[1].xyz;\n\tvec3 c2 = m[2].xyz;\n\tvec3 n0 = cross(c1, c2);\n\tvec3 n1 = cross(c2, c0);\n\tvec3 n2 = cross(c0, c1);\n\t// Mirrored transforms (negative determinant) would flip normals inward.\n\tfloat s = dot(c0, n0) < 0.0 ? -1.0 : 1.0;\n\treturn mat3(n0 * s, n1 * s, n2 * s);\n}\n\n\n#define MAX_BONES 64\n\nattribute vec4 a_boneWeights;  // Bone weights (4 influences per vertex)\nattribute vec4 a_boneIndices;  // Bone indices (4 influences per vertex)\n\nuniform int u_useSkinning;     // Whether to apply skinning (1 = yes, 0 = no)\n\n#ifdef USE_INSTANCING\nuniform sampler2D u_boneTexture;\nuniform vec2 u_boneTextureSize; // (width, height) in texels\n\nmat4 getBoneMatrix(float boneIndex) {\n\tfloat row = a_instanceMaterial.w;\n\tvec2 inv = 1.0 / u_boneTextureSize;\n\tfloat v = (row + 0.5) * inv.y;\n\tfloat x = boneIndex * 4.0;\n\treturn mat4(\n\t\ttexture2D(u_boneTexture, vec2((x + 0.5) * inv.x, v)),\n\t\ttexture2D(u_boneTexture, vec2((x + 1.5) * inv.x, v)),\n\t\ttexture2D(u_boneTexture, vec2((x + 2.5) * inv.x, v)),\n\t\ttexture2D(u_boneTexture, vec2((x + 3.5) * inv.x, v))\n\t);\n}\n#else\nuniform mat4 u_boneMatrices[MAX_BONES];\n\nmat4 getBoneMatrix(float boneIndex) {\n\treturn u_boneMatrices[int(boneIndex)];\n}\n#endif\n\nmat4 getSkinMatrix() {\n\treturn\n\t\ta_boneWeights.x * getBoneMatrix(a_boneIndices.x) +\n\t\ta_boneWeights.y * getBoneMatrix(a_boneIndices.y) +\n\t\ta_boneWeights.z * getBoneMatrix(a_boneIndices.z) +\n\t\ta_boneWeights.w * getBoneMatrix(a_boneIndices.w);\n}\n\n\n// Uniforms\nuniform mat4 u_viewMatrix;       // Camera view matrix\nuniform mat4 u_projectionMatrix; // Camera projection matrix\nuniform vec3 u_cameraPosition;   // Camera world position\n\n// Shadow mapping uniforms\nuniform mat4 u_lightSpaceMatrix; // Light view * projection matrix for shadow mapping\nuniform float u_shadowNormalOffset; // Normal offset to prevent shadow acne\n\n// Varyings passed to fragment shader\nvarying vec3 v_worldPosition;    // Position in world space\nvarying vec3 v_worldNormal;      // Normal in world space\nvarying vec2 v_uv;               // Texture coordinates\nvarying vec3 v_viewDirection;    // Direction from surface to camera\nvarying mat3 v_TBN;              // Tangent-Bitangent-Normal matrix for normal mapping\nvarying vec4 v_lightSpacePos;    // Position in light space for shadow mapping\n\n#ifdef USE_INSTANCING\nvarying vec4 v_instanceColor;\nvarying vec4 v_instanceEmissive;\nvarying vec4 v_instanceMaterial;\n#endif\n\n\nvoid main() {\n\tvec3 skinnedPosition = a_position;\n\tvec3 skinnedNormal = a_normal;\n\tvec3 skinnedTangent = a_tangent.xyz;\n\n\t// Apply skinning if enabled\n\tif (u_useSkinning == 1) {\n\t\tmat4 skinMatrix = getSkinMatrix();\n\n\t\t// Transform position by skin matrix\n\t\tskinnedPosition = (skinMatrix * vec4(a_position, 1.0)).xyz;\n\n\t\t// Transform normal by skin matrix (upper-left 3x3)\n\t\t// Note: For correct normal transformation, we should use inverse transpose,\n\t\t// but for skeletal animation with uniform scales, the upper 3x3 is sufficient\n\t\tmat3 skinMatrix3 = mat3(skinMatrix);\n\t\tskinnedNormal = normalize(skinMatrix3 * a_normal);\n\t\tskinnedTangent = normalize(skinMatrix3 * a_tangent.xyz);\n\t}\n\n\tmat4 worldMatrix = getWorldMatrix();\n\tmat3 normalMatrix = getNormalMatrix(worldMatrix);\n\n\t// Transform position to world space\n\tvec4 worldPos = worldMatrix * vec4(skinnedPosition, 1.0);\n\tv_worldPosition = worldPos.xyz;\n\n\t// Transform normal to world space and normalize\n\tv_worldNormal = normalize(normalMatrix * skinnedNormal);\n\n\t// Calculate view direction (from surface to camera)\n\tv_viewDirection = normalize(u_cameraPosition - worldPos.xyz);\n\n\t// Pass through UV coordinates\n\tv_uv = a_uv;\n\n\t// Calculate TBN matrix for normal mapping\n\tvec3 T = normalize(normalMatrix * skinnedTangent);\n\tvec3 N = v_worldNormal;\n\t// Re-orthogonalize T with respect to N\n\tT = normalize(T - dot(T, N) * N);\n\t// Calculate bitangent\n\tvec3 B = cross(N, T) * a_tangent.w;\n\tv_TBN = mat3(T, B, N);\n\n\t// Calculate position in light space for shadow mapping\n\tvec3 shadowPos = worldPos.xyz + v_worldNormal * u_shadowNormalOffset;\n\tv_lightSpacePos = u_lightSpaceMatrix * vec4(shadowPos, 1.0);\n\n#ifdef USE_INSTANCING\n\tv_instanceColor = a_instanceColor;\n\tv_instanceEmissive = a_instanceEmissive;\n\tv_instanceMaterial = a_instanceMaterial;\n#endif\n\n\t// Transform to clip space\n\tgl_Position = u_projectionMatrix * u_viewMatrix * worldPos;\n}\n";
